/**
 * Shapes for the vector art generated by scripts/build-vectors.py.
 *
 * Each path carries a tone rather than a colour, so the component that draws
 * it picks the fill from the token layer and no generated file holds a hex.
 */

export type ArtTone = "navy" | "cream" | "olive" | "pink";

export type ArtPath = readonly [tone: ArtTone, d: string];

export type ArtGroups = Readonly<Record<string, readonly ArtPath[]>>;
